// Turns Meta's webhook into one item per incoming message. Skips delivery/read receipts and repeats.
const store = $getWorkflowStaticData('global');   // message IDs already handled (saved for active workflows only)
store.seen = store.seen || {};
const now = Date.now();
for (const [id, t] of Object.entries(store.seen)) if (now - t > 7 * 86400000) delete store.seen[id];

const out = [];
$('WhatsApp message received').all().forEach((item, i) => {
  const ev = item.json;
  if (!Array.isArray(ev.messages)) return;                 // status updates, template events and so on
  const contacts = ev.contacts || [];
  for (const m of ev.messages) {
    if (!m.id || store.seen[m.id]) continue;               // Meta can deliver the same webhook more than once
    if (m.type === 'reaction') continue;                   // emoji reactions are not orders
    store.seen[m.id] = now;
    const c = contacts.find(x => (m.from && x.wa_id === m.from) || (m.from_user_id && x.user_id === m.from_user_id)) || contacts[0] || {};
    let text = '';
    if (m.type === 'text') text = (m.text && m.text.body) || '';
    else if (m.type === 'button') text = (m.button && m.button.text) || '';
    else if (m.type === 'interactive') text = (m.interactive && ((m.interactive.button_reply || {}).title || (m.interactive.list_reply || {}).title)) || '';
    else if (m.type === 'image' || m.type === 'document') text = ((m[m.type] || {}).caption) || '';
    out.push({ json: {
      messageId: m.id,
      phoneNumberId: ev.metadata && ev.metadata.phone_number_id,
      waNumber: m.from || c.wa_id || '',                   // phone number, unless the sender uses a WhatsApp username
      userId: m.from_user_id || c.user_id || '',           // business-scoped user ID (sent since 2026)
      profileName: (c.profile && c.profile.name) || '',
      username: (c.profile && c.profile.username) || '',
      type: m.type,
      text: String(text).trim(),
      sentAt: Number(m.timestamp) * 1000,
    }, pairedItem: { item: i } });
  }
});
return out;

// Finds the customer by WhatsApp number and reads product codes and quantities with simple rules.
const s = $('Settings').first().json;
const tz = s.timezone || 'Asia/Singapore';
function readCatalogue(list) {
  const cat = new Map();
  for (const line of String(list || '').split(/\n|;/)) {
    const [code, name, price] = line.split('|').map(x => (x || '').trim());
    if (code) cat.set(code.toUpperCase(), { code: code.toUpperCase(), name: name || code, price: parseFloat(price) || 0 });
  }
  return cat;
}
const catalogue = readCatalogue(s.products);
if (!catalogue.size) throw new Error('Add your products in Settings, one per line: CODE | name | price');
const maxQty = parseInt(s.maxQuantity, 10) || 500;
const esc = x => x.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const codes = [...catalogue.keys()].sort((a, b) => b.length - a.length).map(esc).join('|');
const tokenRe = new RegExp('(?<![A-Z0-9])(' + codes + ')(?![A-Z0-9])|(?<![A-Z0-9.])(\\d+(?:\\.\\d+)?)(?![\\d.])', 'gi');
const looksLikeItem = /\d+\s*(x|×|\*|pcs|pc|ctns?|cartons?|bags?|trays?|packs?|boxes|box|btls?|bottles?|tins?|cases?)\b|\b(x|×)\s*\d+/i;

const digits = v => String(v ?? '').replace(/\D/g, '');
const sgKey = v => { let d = digits(v); if (d.startsWith('00')) d = d.slice(2); if (/^[689]\d{7}$/.test(d)) d = '65' + d; return d; };
function stamp(ms) {
  const p = new Intl.DateTimeFormat('en-GB', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(ms));
  const g = t => p.find(x => x.type === t).value;
  return `${g('year')}-${g('month')}-${g('day')} ${g('hour')}:${g('minute')}`;
}

// Customers sheet: match on WhatsApp number, or on the WhatsApp user ID for people who hide their number
const byPhone = new Map(), byUser = new Map();
for (const r of $('Get customers').all().map(i => i.json)) {
  if (/^(no|n|false|inactive)$/i.test(String(r['Active'] ?? '').trim())) continue;
  const p = sgKey(r['WhatsApp number']);
  if (p) byPhone.set(p, r);
  const u = String(r['WhatsApp user ID'] ?? '').trim();
  if (u) byUser.set(u, r);
}

function readOrder(text) {
  const lines = new Map(), problems = [], notes = [];
  const segments = text.split(/\n|,|;|\+|&|\band\b/i).map(x => x.trim()).filter(Boolean);
  for (const seg of segments) {
    const tokens = [...seg.matchAll(tokenRe)].map(m => m[1] ? { code: m[1].toUpperCase() } : { num: parseFloat(m[2]) });
    if (!tokens.some(t => t.code)) {
      if (looksLikeItem.test(seg)) problems.push(`"${seg}" is not a product code we know`);
      else notes.push(seg);
      continue;
    }
    // Pairs go "code qty, code qty" or "qty code, qty code" depending on how the line starts
    const qtyFirst = tokens[0].num !== undefined;
    const pairs = [];
    for (let i = 0; i < tokens.length; i += 2) {
      const a = tokens[i], b = tokens[i + 1];
      const code = qtyFirst ? (b && b.code) : a.code;
      const qty = qtyFirst ? a.num : (b && b.num);
      if (!code || qty === undefined) { pairs.length = 0; break; }
      pairs.push({ code, qty });
    }
    if (!pairs.length) {
      problems.push(tokens.some(t => t.num !== undefined) ? `could not pair codes and quantities in "${seg}"`
        : `no quantity given for ${tokens.filter(t => t.code).map(t => t.code).join(', ')}`);
      continue;
    }
    for (const { code, qty } of pairs) {
      if (!Number.isInteger(qty) || qty < 1) { problems.push(`quantity ${qty} for ${code} is not a whole number`); continue; }
      if (qty > maxQty) { problems.push(`${qty} x ${code} is above the ${maxQty} limit, please check`); continue; }
      lines.set(code, (lines.get(code) || 0) + qty);
    }
  }
  return { lines: [...lines].map(([code, qty]) => ({ code, qty, name: catalogue.get(code).name, price: catalogue.get(code).price })), problems, notes };
}

return $('Read the message').all().map((item, i) => {
  const m = item.json;
  const customer = (m.waNumber && byPhone.get(sgKey(m.waNumber))) || (m.userId && byUser.get(m.userId)) || null;
  const replyTo = customer ? (sgKey(customer['WhatsApp number']) || digits(m.waNumber)) : digits(m.waNumber);
  const hoursOld = (Date.now() - m.sentAt) / 3600000;
  const base = {
    ...m,
    receivedAt: stamp(m.sentAt),
    known: !!customer,
    customerName: customer ? String(customer['Customer']) : '',
    contactName: customer ? String(customer['Contact name'] || m.profileName || '') : m.profileName,
    replyTo,
    replyToDisplay: replyTo ? '+' + replyTo : '(hidden: WhatsApp username ' + (m.username || m.userId) + ')',
    canReply: !!replyTo && hoursOld < 23,                  // free-form replies only inside the 24-hour window
    typeLabel: ({ audio: 'a voice message', image: 'a photo', video: 'a video', document: 'a document', location: 'a location', sticker: 'a sticker', contacts: 'a contact card' })[m.type] || 'a ' + m.type + ' message',
    lines: [], problems: [], notes: [], readBy: 'Rules', kind: 'human', reason: '', aiEligible: false,
  };
  const r = m.text ? readOrder(m.text) : { lines: [], problems: [], notes: [] };
  Object.assign(base, r);

  if (!customer) base.reason = replyTo ? 'Number not in the Customers sheet' : 'Sender hides their number (WhatsApp username) and is not in the Customers sheet';
  else if (!m.text) base.reason = `Sent ${base.typeLabel}, not text`;
  else if (/^\s*(change|cancel|amend)\b/i.test(m.text)) base.reason = 'Change or cancel request';
  else if (hoursOld >= 23) base.reason = `Message arrived ${Math.round(hoursOld)} hours late, too old for an automatic WhatsApp reply`;
  else if (r.lines.length && !r.problems.length) base.kind = 'order';
  else {
    base.reason = r.problems.length ? 'Order could not be read fully: ' + r.problems.join('; ') : 'Message from a customer, not an order';
    base.aiEligible = true;                                // the optional AI step may try these
  }
  return { json: base, pairedItem: { item: i } };
});

// Accepts the AI reading only if every code is in the product list and every quantity is sensible.
const s = $('Settings').first().json;
function readCatalogue(list) {
  const cat = new Map();
  for (const line of String(list || '').split(/\n|;/)) {
    const [code, name, price] = line.split('|').map(x => (x || '').trim());
    if (code) cat.set(code.toUpperCase(), { code: code.toUpperCase(), name: name || code, price: parseFloat(price) || 0 });
  }
  return cat;
}
const catalogue = readCatalogue(s.products);
const maxQty = parseInt(s.maxQuantity, 10) || 500;
const m = $('Match customer and read the order').item.json;
const ai = ($json.output && typeof $json.output === 'object') ? $json.output : {};
const items = Array.isArray(ai.items) ? ai.items : [];
const merged = new Map(), bad = [];
for (const it of items) {
  const code = String(it.code || '').toUpperCase().trim();
  const qty = Number(it.quantity);
  if (!catalogue.has(code)) { bad.push(`AI suggested ${code || 'a blank code'}, which is not in the product list`); continue; }
  if (!Number.isInteger(qty) || qty < 1 || qty > maxQty) { bad.push(`AI quantity ${it.quantity} for ${code} failed the check`); continue; }
  merged.set(code, (merged.get(code) || 0) + qty);
}
const unsure = String(ai.unclear || '').trim();
if (unsure) bad.push('AI was unsure: ' + unsure);          // any doubt goes to a person
if (merged.size && !bad.length) {
  return { json: { ...m, kind: 'order', readBy: 'AI (please check)', problems: [], reason: '',
    lines: [...merged].map(([code, qty]) => ({ code, qty, name: catalogue.get(code).name, price: catalogue.get(code).price })),
    notes: [] } };
}
return { json: { ...m, problems: [...m.problems, ...bad],
  reason: m.reason + (items.length ? ' (AI reading rejected: ' + (bad.join('; ') || 'nothing usable') + ')' : ' (AI found no order either)') } };

// Gives the order a number, lays out the sheet row and writes the WhatsApp confirmation.
const s = $('Settings').first().json;
const tz = s.timezone || 'Asia/Singapore';
const store = $getWorkflowStaticData('global');
store.orderSeq = store.orderSeq || {};
const day = new Intl.DateTimeFormat('en-CA', { timeZone: tz }).format(new Date()).replace(/-/g, '');
for (const k of Object.keys(store.orderSeq)) if (k !== day) delete store.orderSeq[k];
const cur = s.currency || 'S$';

return $input.all().map((item, i) => {
  const o = item.json;
  store.orderSeq[day] = (store.orderSeq[day] || 0) + 1;
  const orderId = `WA-${day}-${String(store.orderSeq[day]).padStart(3, '0')}`;
  const priced = o.lines.every(l => l.price > 0);
  const value = priced ? o.lines.reduce((t, l) => t + l.qty * l.price, 0) : 0;
  const parts = (o.contactName || '').trim().split(/\s+/);
  const first = /^(mr|mrs|ms|mdm|madam|miss|dr|uncle|auntie|aunty)\.?$/i.test(parts[0]) ? parts.slice(0, 2).join(' ') : parts[0];
  const reply = [
    `Thanks${first ? ' ' + first : ''}! Order *${orderId}* for ${o.customerName} received:`,
    ...o.lines.map(l => `• ${l.qty} x ${l.name} (${l.code})`),
    priced ? `Estimated ${cur}${value.toFixed(2)} before GST.` : '',
    o.readBy.startsWith('AI') ? 'We read this order automatically, so please check the items above.' : '',
    s.deliveryNote,
    'If anything is wrong, reply CHANGE and our team will sort it out.',
  ].filter(Boolean).join('\n');
  return { json: {
    ...o,
    orderId,
    itemsText: o.lines.map(l => `${l.qty} x ${l.code} ${l.name}`).join('; '),
    estimatedValue: priced ? value.toFixed(2) : '',
    status: 'New',
    notesText: o.notes.join('; '),
    replyText: reply,
  }, pairedItem: { item: i } };
});

// Tells staff what needs a person, and decides whether the customer gets a short holding reply.
const s = $('Settings').first().json;
const o = $json;
const who = o.known ? `${o.customerName} (${o.contactName || 'no contact name'})` : (o.profileName || 'Unknown sender');
const subject =
  !o.known ? `WhatsApp from an unknown ${o.replyTo ? 'number ' + o.replyToDisplay : 'sender'}: ${o.profileName || 'no name'}`
  : /^Change/.test(o.reason) ? `Change request on WhatsApp from ${o.customerName}`
  : /^Order could not/.test(o.reason) ? `Check WhatsApp order from ${o.customerName}`
  : /^Sent /.test(o.reason) ? `${o.customerName} sent ${o.typeLabel} on WhatsApp`
  : /late/.test(o.reason) ? `Late WhatsApp message from ${o.customerName}: confirm by hand`
  : `WhatsApp message from ${o.customerName}`;
const understood = o.lines.length ? o.lines.map(l => `- ${l.qty} x ${l.code} ${l.name}`).join('\n') : '- nothing';
const body = [
  `From: ${who}`,
  `WhatsApp: ${o.replyToDisplay}${o.replyTo ? '   Chat: https://wa.me/' + o.replyTo : ''}`,
  `Received: ${o.receivedAt}`,
  `Why this needs you: ${o.reason}`,
  '',
  `Message:\n${o.text || '(' + o.type + ' message: open WhatsApp to see it)'}`,
  '',
  `What the automation understood:\n${understood}`,
  '',
  o.known ? 'Nothing was added to the Orders sheet. Add or correct the order there, then reply to the customer.'
          : 'If this is a new customer, add them to the Customers sheet so their next order is read automatically.',
].join('\n');
const holding = o.known && o.canReply && (/^Order could not/.test(o.reason) || /^Change/.test(o.reason));
return { json: {
  ...o,
  alertSubject: subject,
  alertBody: body,
  sendHoldingReply: holding,
  holdingText: /^Change/.test(o.reason)
    ? 'Thanks, we have your message. A member of our team will confirm the change shortly.'
    : 'Thanks, we have your order. We could not read every item automatically, so a member of our team will confirm it shortly.',
}};

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "items": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "code": {
            "type": "string",
            "description": "Product code from the list"
          },
          "quantity": {
            "type": "number",
            "description": "Whole number of units"
          }
        },
        "required": [
          "code",
          "quantity"
        ]
      }
    },
    "unclear": {
      "type": "string",
      "description": "Anything you could not read with confidence"
    }
  },
  "required": [
    "items"
  ]
}
